/**
 * Caption-track METADATA extraction from YouTube's player response object.
 * LL-001 deliberately does not return or request `baseUrl` (the private timedtext endpoint);
 * it only records whether one is present.
 */
export interface CaptionTrackInfo {
  languageCode: string;
  name: string;
  /** "asr" means auto-generated (automatic speech recognition). */
  kind: string | null;
  isAutoGenerated: boolean;
  vssId: string | null;
  isTranslatable: boolean;
  hasBaseUrl: boolean;
}

export interface TrackProbeResult {
  ok: boolean;
  /** Where the player response came from. */
  via: 'movie_player.getPlayerResponse' | 'ytInitialPlayerResponse' | 'none';
  /** videoId inside the player response; compare to the URL to detect stale data. */
  responseVideoId: string | null;
  tracks: CaptionTrackInfo[];
  translationLanguageCount: number;
  error?: string;
}

export const PROBE_REQUEST = 'LL001_PROBE_REQUEST';
export const PROBE_RESULT = 'LL001_PROBE_RESULT';

function asRecord(v: unknown): Record<string, unknown> | null {
  return v !== null && typeof v === 'object' ? (v as Record<string, unknown>) : null;
}

function textOf(v: unknown): string {
  const r = asRecord(v);
  if (!r) return '';
  if (typeof r.simpleText === 'string') return r.simpleText;
  if (Array.isArray(r.runs)) return r.runs.map((x) => (asRecord(x)?.text as string) ?? '').join('');
  return '';
}

/** Pure function: safe to run against any unknown object. */
export function extractTrackInfo(playerResponse: unknown, via: TrackProbeResult['via']): TrackProbeResult {
  const pr = asRecord(playerResponse);
  if (!pr) return { ok: false, via, responseVideoId: null, tracks: [], translationLanguageCount: 0, error: 'no player response' };
  const videoDetails = asRecord(pr.videoDetails);
  const responseVideoId = typeof videoDetails?.videoId === 'string' ? videoDetails.videoId : null;
  const renderer = asRecord(asRecord(pr.captions)?.playerCaptionsTracklistRenderer);
  const rawTracks = Array.isArray(renderer?.captionTracks) ? renderer.captionTracks : [];
  const tracks: CaptionTrackInfo[] = [];
  for (const t of rawTracks) {
    const r = asRecord(t);
    if (!r) continue;
    const kind = typeof r.kind === 'string' ? r.kind : null;
    tracks.push({
      languageCode: typeof r.languageCode === 'string' ? r.languageCode : '',
      name: textOf(r.name),
      kind,
      isAutoGenerated: kind === 'asr',
      vssId: typeof r.vssId === 'string' ? r.vssId : null,
      isTranslatable: r.isTranslatable === true,
      hasBaseUrl: typeof r.baseUrl === 'string' && r.baseUrl.length > 0,
    });
  }
  const translationLanguageCount = Array.isArray(renderer?.translationLanguages) ? renderer.translationLanguages.length : 0;
  return { ok: true, via, responseVideoId, tracks, translationLanguageCount };
}

/** Validates a message posted from the MAIN-world probe (the page could forge one). */
export function isProbeResultMessage(data: unknown, nonce: string): data is { type: string; nonce: string; result: TrackProbeResult } {
  const r = asRecord(data);
  if (!r || r.type !== PROBE_RESULT || r.nonce !== nonce) return false;
  const res = asRecord(r.result);
  return !!res && typeof res.ok === 'boolean' && Array.isArray(res.tracks);
}
